export function ProgressChecklist({
  title = "{{title}}",
  completed = {{completed}},
  total = {{total}},
  accent = "{{accent}}",
  style = "{{style}}",
}) {
  const pct = Math.min(100, (completed / total) * 100);
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, maxWidth: 300, borderRadius: 14, border: "1px solid #24143018", textAlign: "center" }}>
      <h3 style={{ margin: "0 0 14px", fontSize: 15, fontWeight: 700, textAlign: "left" }}>{title}</h3>
      {style === "bar" && (
        <div style={{ height: 8, borderRadius: 4, background: "#24143018", overflow: "hidden", marginBottom: 10 }}>
          <span style={{ display: "block", height: "100%", width: pct + "%", background: accent, borderRadius: 4 }} />
        </div>
      )}
      {style === "ring" && (
        <div style={{ width: 88, height: 88, borderRadius: 999, display: "inline-flex", alignItems: "center", justifyContent: "center", marginBottom: 10, background: "conic-gradient(" + accent + " " + pct + "%, #24143018 0)" }}>
          <span style={{ width: 64, height: 64, borderRadius: 999, background: "#FAF7F2" }} />
        </div>
      )}
      {style === "fraction" && (
        <p style={{ fontSize: 34, fontWeight: 800, color: accent, margin: "6px 0" }}>{completed} <span style={{ fontSize: 14, fontWeight: 500, color: "#24143090" }}>of {total}</span></p>
      )}
      <p style={{ margin: 0, fontSize: 12, color: "#24143090", textAlign: "left" }}>{completed} of {total} steps complete</p>
    </div>
  );
}
